function tokenPrediction(s){
  const chip=x=>`<span class="token-chip ${x==='='?'equals':''}">${E(x)}</span>`;
  const branches=s.token_branches||[];
  const equation=s.math_equation?`<div class="token-equation" aria-label="Équation mathématique : ${E(s.math_equation.numerator)} divisé par ${E(s.math_equation.denominator)}, égal à"><span class="math-fraction"><span>${E(s.math_equation.numerator)}</span><span>${E(s.math_equation.denominator)}</span></span><b>=</b></div>`:'';
  return `<div class="token-prediction-scene"><div class="token-prediction-head"><div class="kicker">${E(s.eyebrow||s.section)}</div><h1>${E(s.title)}</h1><p>${E(s.screen_secondary||'')}</p></div>${equation}<div class="token-prompt"><div class="token-prompt-label">PROMPT TOKENISÉ · SCHÉMA PÉDAGOGIQUE</div><div class="token-stream">${(s.input_tokens||[]).map(chip).join('')}</div><div class="token-space-key">␠ = espace ; découpage exact variable selon le tokenizer</div></div><div class="token-branch-intro"><span>=</span><div>APRÈS LE SIGNE ÉGAL, LE MODÈLE SCORE DES TOKENS CANDIDATS</div></div><div class="token-branches" role="img" aria-label="Exemples de branches de tokens possibles après le signe égal">${branches.map((b,i)=>`<div class="token-branch"><div class="token-branch-label">${E(b.label)}</div><div class="token-branch-path">${b.tokens.map((x,j)=>`${j?'<b>→</b>':''}${chip(x)}`).join('')}</div><div class="token-branch-note">${E(b.note)}</div></div>`).join('')}</div><div class="token-topk-note">${E(s.topk_note||'')}</div><div class="token-prediction-takeaway">${E(s.bottom)}</div></div>`;
}

