function methodologyScene(s){
  const m=s.method||{},items=m.items||[];
  let content='';
  if(m.variant==='quote') content=`<div class="method-quote">${m.tag?`<small>${E(m.tag)}</small>`:''}<blockquote>${E(m.screen)}</blockquote>${m.example?`<p>${E(m.example)}</p>`:''}</div>`;
  else if(m.variant==='prompt') content=`<div class="method-prompt"><small>À DIRE À L’ASSISTANT</small><blockquote>${E(m.prompt)}</blockquote>${m.example?`<p>${E(m.example)}</p>`:''}</div>`;
  else if(m.variant==='roles') content=`<div class="method-roles">${m.cards.map((card,i)=>`<article class="method-role role-${i}"><small>RÔLE 0${i+1}</small><h2>${E(card.title)}</h2><ul>${card.items.map(x=>`<li>${E(x)}</li>`).join('')}</ul></article>`).join('')}</div>`;
  else if(m.variant==='chain') content=`<div class="method-chain count-${items.length}">${items.map((x,i)=>`<article><small>${String(i+1).padStart(2,'0')}</small><b>${E(x)}</b></article>`).join('')}</div>${m.tag?`<div class="method-label">${E(m.tag)}</div>`:''}`;
  else if(m.variant==='grid') content=`<div class="method-grid count-${items.length}">${items.map((x,i)=>`<article><small>${String(i+1).padStart(2,'0')}</small><b>${E(x)}</b></article>`).join('')}</div>`;
  else if(m.variant==='tree') content=`<div class="method-tree"><div class="method-tree-root">${E(m.tag||'DOSSIER DE PROJET')}</div><div class="method-tree-files">${items.map((x,i)=>`<div><small>${String(i+1).padStart(2,'0')}</small><b>${E(x)}</b></div>`).join('')}</div><p>Des fichiers courts, nommés clairement et faciles à transmettre.</p></div>`;
  else if(m.variant==='verbs') content=`<div class="method-verbs">${items.map((x,i)=>`<article><small>${String(i+1).padStart(2,'0')}</small><b>${E(x)}</b></article>`).join('')}</div>`;
  else if(m.variant==='exercise') content=`<div class="method-exercise"><div class="method-time">${E(m.time||'EXERCICE')}</div><div class="method-exercise-steps">${items.map((x,i)=>`<article><small>ÉTAPE 0${i+1}</small><b>${E(x)}</b></article>`).join('')}</div></div>`;
  const visual=s.image?`<figure class="method-visual"><img src="${asset(s.image)}" alt="${E(s.image_alt||'Illustration éditoriale de la méthode de projet')}"></figure>`:'';
  return `${header(s)}${stage(`<div class="methodology-content${s.image?' has-visual':''}"><div class="method-text">${content}</div>${visual}</div>`)}${footer(s)}`;
}
function biasModule(s){
  const b=s.bias||{};
  let content='';
  if(b.kind==='hook') content=`<div class="bias-hook"><p>${E(b.question)}</p><div>${E(b.secondary)}</div><small>${E(b.question2)}</small></div>`;
  else if(b.kind==='evidence') content=`<div class="bias-evidence">${b.cards.map((c,i)=>`<article class="bias-evidence-card evidence-${i}"><small>${E(c.kicker)}</small><h2>${E(c.title)}</h2><p>${E(c.text)}</p><footer>${E(c.source)}</footer></article>`).join('')}</div><div class="bias-caveat">${E(b.caveat)}</div>`;
  else if(b.kind==='pitfalls') content=`<div class="bias-pitfalls">${b.cards.map((c,i)=>`<article><small>0${i+1}</small><h2>${E(c.title)}</h2><p>${E(c.text)}</p></article>`).join('')}</div><div class="bias-caveat">${E(b.caveat)}</div>`;
  else if(b.kind==='situations') content=`<div class="bias-situations">${b.cards.map((c,i)=>`<article><small>0${i+1} · ${E(c.title)}</small><blockquote>${E(c.quote)}</blockquote><p><b>Risque :</b> ${E(c.risk)}</p></article>`).join('')}</div>`;
  else if(b.kind==='reflexes') content=`<div class="bias-reflexes">${b.cards.map((c,i)=>`<article><small>0${i+1}</small><h2>${E(c.title)}</h2><p>${E(c.text)}</p></article>`).join('')}</div><div class="bias-caveat">${E(b.caveat)}</div>`;
  else if(b.kind==='prompts') content=`<div class="bias-prompts">${b.cards.map((c,i)=>`<article><small>0${i+1} · ${E(c.title)}</small><blockquote>${E(c.prompt)}</blockquote><span>À COPIER</span></article>`).join('')}</div>`;
  else if(b.kind==='levels') content=`<div class="bias-levels">${b.cards.map((c,i)=>`<article class="level-${i}"><small>${E(c.level)}</small><h2>${E(c.title)}</h2><p>${E(c.context)}</p><div><b>Contrôles</b>${E(c.control)}</div></article>`).join('')}</div><div class="bias-caveat">${E(b.caveat)}</div>`;
  else if(b.kind==='close') content=`<div class="bias-close"><blockquote>${E(b.statement)}</blockquote><div class="bias-close-questions">${b.questions.map((q,i)=>`<p><small>0${i+1}</small>${E(q)}</p>`).join('')}</div><div class="bias-close-final">${E(b.final)}</div></div>`;
  return `${header(s)}${stage(`<div class="bias-stage">${content}</div>`)}${footer(s)}`;
}
