function textContinuation(s){
  const isAnswer=s.continuation_type==='answer';
  return `<section class="text-continuation-scene ${isAnswer?'is-answer':'is-prompt'}"><div class="text-continuation-index">${String(s.source_row).padStart(2,'0')}</div><div class="text-continuation-kicker">${E(s.eyebrow||s.title)}</div><div class="text-continuation-copy">${E(s.screen_primary||s.title)}</div><div class="text-continuation-status">${E(s.screen_secondary||'')}</div><div class="text-continuation-rule"></div><div class="text-continuation-note">${E(s.bottom||'')}</div></section>`;
}
function privacyPipeline(s){
  const items=s.items||[];
  const node=(item,cls)=>`<section class="pp-node ${cls}"><div class="pp-node-label">${E(item?.[0]||'')}</div><p>${E(item?.[1]||'')}</p></section>`;
  return `<section class="privacy-pipeline-scene"><header class="pp-head"><div class="kicker">${E(s.section||'SÉCURISER')}</div><h1>${E(s.title)}</h1><p>${E(s.screen_secondary||'')}</p></header><div class="pp-flow">${node(items[0],'pp-document')}<div class="pp-arrow" aria-hidden="true">→</div><section class="pp-sas"><div class="pp-node-label">${E(items[1]?.[0]||'')}</div><p>${E(items[1]?.[1]||'')}</p><div class="pp-transforms"><span>Masquer</span><span>Pseudonymiser</span><span>Généraliser</span><span>Supprimer ou agréger</span></div></section><div class="pp-arrow" aria-hidden="true">→</div>${node(items[2],'pp-minimized')}<div class="pp-arrow" aria-hidden="true">→</div>${node(items[3],'pp-llm')}</div><aside class="pp-distinction"><div><b>Pseudonymiser</b><span>La clé de retour reste séparée et sous contrôle.</span></div><div><b>Anonymiser</b><span>La réidentification doit devenir raisonnablement impossible.</span></div></aside><div class="pp-takeaway">${E(s.bottom||'')}</div></section>`;
}
function piiDefinition(s){const p=s.pii||{};const card=(label,text,kind='')=>`<article class="pii-card ${kind}"><span>${E(label)}</span><p>${E(text)}</p></article>`;return `<section class="pii-definition-scene"><article class="pii-card pii-core"><span>PII / DONNÉE PERSONNELLE</span><h2>${E(p.definition||'Une information liée à une personne identifiée ou identifiable.')}</h2><p>Le terme PII est courant en anglais. En France, le RGPD parle de donnée à caractère personnel.</p></article><section class="pii-identifiers">${card('IDENTIFIANT DIRECT',p.direct||'Nom, numéro de sécurité sociale, numéro de passeport.')} ${card('IDENTIFIANT INDIRECT',p.indirect||'Adresse IP, localisation ou recoupement de plusieurs informations.','is-indirect')}</section><section class="pii-risks">${card('RISQUE À ÉVALUER',p.ordinary||'E-mail professionnel, téléphone ou identifiant : à protéger selon le contexte.')} ${card('VIGILANCE RENFORCÉE',p.high||'Santé, biométrie d’identification, finances. Certaines données relèvent de l’article 9 du RGPD.','is-high')}</section><div class="pii-gate"><span>AVANT L’ENVOI</span><b>Autorisé ?</b><b>Sensible ?</b><b>Nécessaire ?</b></div></section>`;}
function llmIntro(s){const d=s.llm||{};return `<section class="llm-intro-scene"><article class="llm-part"><span>CE QUE NOUS VENONS DE VOIR</span><h2>${E(d.machine_learning||'Machine learning')}</h2><p>${E(d.machine_learning_note||'Apprendre des régularités à partir d’exemples.')}</p></article><div class="llm-operator" aria-hidden="true">+</div><article class="llm-part"><span>NOUVELLE MATIÈRE</span><h2>${E(d.language||'Langage')}</h2><p>${E(d.language_note||'Des textes, des mots et leur contexte.')}</p></article><div class="llm-arrow" aria-hidden="true">→</div><article class="llm-result"><span>LE RÉSULTAT</span><strong>LLM</strong><b>${E(d.expanded||'Large Language Model')}</b><p>${E(d.french||'Grand modèle de langage')}</p></article></section>`;}
function thinkingBottleneck(s){
  const before=s.before||{},after=s.after||{};
  const column=(kind,label,data)=>`<article class="bottleneck-column ${kind}"><div class="bottleneck-label">${E(label)}</div><div class="bottleneck-ratio"><div><b>${E(data.thinking||'')}</b><span>${E(data.thinking_label||'')}</span></div><i> / </i><div><b>${E(data.execution||'')}</b><span>${E(data.execution_label||'')}</span></div></div><div class="bottleneck-copy">${(data.points||[]).map(x=>`<p>${E(x)}</p>`).join('')}</div></article>`;
  return `<section class="thinking-bottleneck-scene">${column('before','AVANT L’IA',before)}${column('after','AVEC L’IA / AGENTS',after)}<aside class="bottleneck-rule"><span>AVANT DE LANCER L’AGENT</span><b>${E(s.mini_rule||'')}</b><small>${E(s.evidence_note||'')}</small></aside></section>`;
}
function métierProcess(s){
  const steps=s.steps||[];
  return `<section class="metier-process-scene"><div class="metier-process-line">${steps.map((step,i)=>`<article class="metier-step"><small>${String(i+1).padStart(2,'0')}</small><b>${E(step)}</b></article>`).join('')}</div><div class="metier-process-expert"><span>LE SAVOIR-FAIRE À RENDRE EXPLICITE</span><b>${E(s.short_text||'')}</b></div></section>`;
}
function workGraph(s){
  const nodes=s.nodes||[];
  return `<section class="work-graph-scene"><div class="work-graph-canvas" aria-label="Graphe de travail">${nodes.map((node,i)=>`<article class="graph-node node-${i}${node.kind?` kind-${node.kind}`:''}"><small>${node.tag?E(node.tag):String(i+1).padStart(2,'0')}</small><b>${E(node.label)}</b>${node.note?`<span>${E(node.note)}</span>`:''}</article>`).join('')}${nodes.slice(1).map((_,i)=>`<i class="graph-link link-${i}"></i>`).join('')}</div>${s.short_text?`<p class="work-graph-copy">${E(s.short_text)}</p>`:''}</section>`;
}
function closingScene(s){
  const launch=s.launch?.asset?asset(s.launch.asset):s.launch?.href;
  const target=s.launch?.new_window===false?'_self':'_blank';
  const download=s.launch?.download?` download="${E(s.launch.download===true?'':s.launch.download)}"`:'';
  const control=launch&&s.launch?.kind==='audio'
    ? `<div class="closing-audio-controls" aria-label="Commandes de lecture audio"><button type="button" class="closing-launch" data-action="launch-audio" data-audio="${E(launch)}" aria-pressed="false"><span aria-hidden="true">▶</span>${E(s.launch.label||'Écouter l’enregistrement')}</button><button type="button" class="closing-audio-command" data-action="stop-audio"><span aria-hidden="true">■</span>Stop</button><button type="button" class="closing-audio-command" data-action="restart-audio" data-audio="${E(launch)}"><span aria-hidden="true">↺</span>Recommencer au début</button></div>`
    : launch?`<a class="closing-launch" href="${E(launch)}" target="${target}"${target==='_blank'?' rel="noopener"':''}${download}><span aria-hidden="true">↗</span>${E(s.launch.label||'Ouvrir le document')}</a>`:'';
  return `<section class="closing-scene"><div class="closing-rule"></div><div class="closing-kicker">${E(s.section||'Clôture')}</div><h1>${E(s.screen_primary||s.title)}</h1><p>${E(s.screen_secondary||'')}</p>${control}</section>`;
}
