let launchAudioPlayer=null,launchAudioButton=null;
function launchAudio(src,button){
  if(!launchAudioPlayer||launchAudioPlayer.dataset.source!==src){
    launchAudioPlayer?.pause();
    launchAudioPlayer=new Audio(src);
    launchAudioPlayer.dataset.source=src;
    launchAudioPlayer.addEventListener('ended',()=>{launchAudioButton?.classList.remove('is-playing');launchAudioButton?.setAttribute('aria-pressed','false');});
  }
  launchAudioButton?.classList.remove('is-playing');
  launchAudioButton=button;
  launchAudioPlayer.play().then(()=>{button.classList.add('is-playing');button.setAttribute('aria-pressed','true');}).catch(()=>toast('Lecture audio impossible dans ce navigateur.'));
  launchAudioPlayer.onpause=()=>{button.classList.remove('is-playing');button.setAttribute('aria-pressed','false');};
}
function stopAudio(){
  if(!launchAudioPlayer)return;
  launchAudioPlayer.pause();
  launchAudioPlayer.currentTime=0;
  launchAudioButton?.classList.remove('is-playing');
  launchAudioButton?.setAttribute('aria-pressed','false');
}
function restartAudio(src,button){
  const playButton=button.closest('.closing-audio-controls')?.querySelector('[data-action="launch-audio"]');
  if(!launchAudioPlayer||launchAudioPlayer.dataset.source!==src){launchAudio(src,playButton);return;}
  launchAudioPlayer.currentTime=0;
  launchAudioButton=playButton;
  launchAudioPlayer.play().then(()=>{playButton?.classList.add('is-playing');playButton?.setAttribute('aria-pressed','true');}).catch(()=>toast('Lecture audio impossible dans ce navigateur.'));
}
