document.addEventListener('click',e=>{const bt=e.target.closest('button');if(!bt)return;const ac=bt.dataset.action;if(bt.hasAttribute('data-index')){show(+bt.dataset.index);closeOverlays();}if(bt.dataset.tab){drawerTab=bt.dataset.tab;fillDrawer();}if(bt.classList.contains('close'))closeOverlays();if(ac==='launch-audio')launchAudio(bt.dataset.audio,bt);if(ac==='stop-audio')stopAudio();if(ac==='restart-audio')restartAudio(bt.dataset.audio,bt);if(ac?.startsWith('matrix-')){const s=D.slides[idx],p=matrixPages[idx]??0,count=matrixPageCount(s),np=(p+(ac==='matrix-next'?1:-1)+count)%count;matrixPages[idx]=np;const m=matrixData(s,np);els[idx].querySelector('.matrix-table').innerHTML=matrixTable(m.headers,m.rows);els[idx].querySelector('.matrix-page').textContent=matrixPageLabel(s,np);}});
